package com.fifotech.task.controller;
import com.fifotech.task.domain.User;import com.fifotech.task.dto.ApiDtos.TaskResponse;import com.fifotech.task.service.TaskService;import com.lowagie.text.*;import com.lowagie.text.pdf.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.awt.Color;import java.io.*;import java.time.*;import java.util.List;
@RestController @RequestMapping("/api/reports") public class ReportController {private final TaskService tasks;public ReportController(TaskService tasks){this.tasks=tasks;}@GetMapping(value="/tasks/pdf",produces="application/pdf") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public ResponseEntity<byte[]> pdf(@AuthenticationPrincipal User actor)throws Exception{List<TaskResponse> rows=tasks.report(actor);ByteArrayOutputStream out=new ByteArrayOutputStream();Document doc=new Document(PageSize.A4.rotate(),28,28,32,32);PdfWriter.getInstance(doc,out);doc.open();Font title=FontFactory.getFont(FontFactory.HELVETICA_BOLD,18,new Color(20,38,68));doc.add(new Paragraph("Task Management Report",title));doc.add(new Paragraph("Generated "+LocalDateTime.now()+" | "+actor.getRole()+" | "+actor.getFullName()));doc.add(Chunk.NEWLINE);PdfPTable table=new PdfPTable(new float[]{3,2,2,1.3f,1.3f,2});table.setWidthPercentage(100);for(String h:List.of("Task","Assignee","Assigned by","Status","Priority","Deadline")){PdfPCell c=new PdfPCell(new Phrase(h,FontFactory.getFont(FontFactory.HELVETICA_BOLD,10,Color.WHITE)));c.setBackgroundColor(new Color(20,38,68));c.setPadding(7);table.addCell(c);}for(TaskResponse t:rows){table.addCell(t.title());table.addCell(t.assigneeName());table.addCell(t.assignerName());table.addCell(t.status().name());table.addCell(t.priority().name());table.addCell(t.deadline()==null?"-":t.deadline().toString());}doc.add(table);doc.close();return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=task-report.pdf").body(out.toByteArray());}}
